   132  void HadesGC::HeapSegment::transitionToFreelist() {
   133    assert(bumpAllocMode_ && "This segment has already been transitioned");
   134    // Add a free list cell that spans the distance from end to level.
   135    const uint32_t sz = end() - level();
   136    if (sz < minAllocationSize()) {
   137      // There's not enough space to add a free list node.
   138      // That's ok, the segment is still well-formed. To eventually reclaim this
   139      // space, the sweeper should coalesce this tail space when the last object
   140      // is free'd.
   141      bumpAllocMode_ = false;
   142      allocatedBytes_ = used();
   143      return;
   144    }
   145    AllocResult res = bumpAlloc(sz);
   146    assert(res.success && "Failed to bump the level to the end");
   147    bumpAllocMode_ = false;
   148    allocatedBytes_ = used();
   149    addCellToFreelist(res.ptr, sz);
   150  }
