   223  AllocResult HadesGC::HeapSegment::bumpAlloc(uint32_t sz) {
   224    assert(
   225        bumpAllocMode_ && "Shouldn't use bumpAlloc except on specific segments");
   226    // Don't use a free list for bump allocation.
   227    AllocResult res = AlignedHeapSegment::alloc(sz);
   228    if (res.success) {
   229      // Set the cell head for any successful alloc, so that write barriers can
   230      // move from dirty cards to the head of the object.
   231      setCellHead(static_cast<GCCell *>(res.ptr));
   232      // No need to change allocatedBytes_ here, as AlignedHeapSegment::used()
   233      // already tracks that. Once the cell is transitioned to freelist mode the
   234      // right value will be stored in allocatedBytes_.
   235    }
   236    return res;
   237  }
