   239  AllocResult HadesGC::HeapSegment::youngGenBumpAlloc(uint32_t sz) {
   240    assert(bumpAllocMode_ && "Shouldn't use youngGenBumpAlloc on an OG segment");
   241    // The only difference between bumpAlloc and youngGenBumpAlloc is that the
   242    // latter doesn't need to set cell heads because YG never has dirty cards that
   243    // need to be scanned.
   244    return AlignedHeapSegment::alloc(sz);
   245  }
