   251  void HadesGC::HeapSegment::addCellToFreelist(void *addr, uint32_t sz) {
   252    assert(
   253        !bumpAllocMode_ &&
   254        "Segment should call transitionToFreelist before calling "
   255        "addCellToFreelist");
   256    assert(contains(addr) && "This segment doesn't contain the cell");
   257    assert(
   258        sz >= sizeof(FreelistCell) &&
   259        "Cannot construct a FreelistCell into an allocation in the OG");
   260    assert(
   261        allocatedBytes_ >= sz &&
   262        "Free'ing a cell that is larger than what is left allocated");
   263    // Turn this into a FreelistCell by constructing in-place.
   264    // TODO: For concurrent access it's probably better to append to the
   265    // tail instead. Only requires writing a single next pointer instead
   266    // of the two-phase head swap + next pointer change.
   267    auto *const newFreeCell = new (addr) FreelistCell{sz, freelistHead_};
   268    freelistHead_ = newFreeCell;
   269    // We free'd this many bytes.
   270    allocatedBytes_ -= sz;
   271    // In ASAN builds, poison the memory outside of the FreelistCell so that
   272    // accesses are flagged as illegal.
   273    // Here, and in other places where FreelistCells are poisoned, use +1 on the
   274    // pointer to skip towards the memory region directly after the FreelistCell
   275    // header of a cell. This way the header is always intact and readable, and
   276    // only the contents of the cell are poisoned.
   277    __asan_poison_memory_region(newFreeCell + 1, sz - sizeof(FreelistCell));
   278  }
