   284  GCCell *HadesGC::HeapSegment::getCellHead(const void *address) {
   285    MarkBitArrayNC &heads = cellHeads();
   286    auto ind = heads.addressToIndex(address);
   287    // Go backwards from the current address looking for a marked bit, which means
   288    // that the address contains a GCCell header.
   289    // TODO: Optimize this with zero scanning.
   290    while (!heads.at(ind)) {
   291      // There is guaranteed to be a marked cell head before ind reaches 0,
   292      // because the intial free list creation of the segment sets the first head.
   293      assert(ind && "About to walk off the end of the object heads table");
   294      --ind;
   295    }
   296    GCCell *cell = reinterpret_cast<GCCell *>(heads.indexToAddress(ind));
   297    assert(
   298        cell->isValid() && "Object heads table doesn't point to a valid object");
   299    return cell;
   300  }
