  1085  void HadesGC::sweep() {
  1086    // Sweep phase: iterate through dead objects and add them to the
  1087    // free list. Also finalize them at this point.
  1088    // Sweeping only needs to pause the OG.
  1089    // TODO: Make sweeping either yield the old gen lock regularly, or not
  1090    // require the lock at all.
  1091    std::lock_guard<Mutex> lk{oldGenMutex_};
  1092    concurrentPhase_.store(Phase::Sweep, std::memory_order_release);
  1093    const bool isTrackingIDs = getIDTracker().isTrackingIDs() ||
  1094        getAllocationLocationTracker().isEnabled();
  1095    for (auto segit = oldGenBegin(), segitend = oldGenEnd(); segit != segitend;
  1096         ++segit) {
  1097      HeapSegment &seg = **segit;
  1098      if (seg.allocatedBytes() == 0) {
  1099        // Quickly skip empty segments.
  1100        continue;
  1101      }
  1102      seg.forAllObjs([this, isTrackingIDs, &seg](GCCell *cell) {
  1103        // forAllObjs skips free list cells, so no need to check for those.
  1104        assert(cell->isValid() && "Invalid cell in sweeping");
  1105        if (HeapSegment::getCellMarkBit(cell)) {
  1106          return;
  1107        }
  1108        // Cell is dead, run its finalizer first if it has one.
  1109        cell->getVT()->finalizeIfExists(cell, this);
  1110        if (seg.isBumpAllocMode()) {
  1111          // If anything was freed, transition from bump-alloc to freelist mode.
  1112          // This has to be done immediately in order for the addCellToFreelist
  1113          // function to work.
  1114          seg.transitionToFreelist();
  1115        }
  1116        // Now add it to the head of the free list for the segment it's
  1117        // in.
  1118        seg.addCellToFreelist(cell);
  1119        if (isTrackingIDs) {
  1120          // There is no race condition here, because the object has already been
  1121          // determined to be dead, so nothing can be accessing it, or asking for
  1122          // its ID.
  1123          getIDTracker().untrackObject(cell);
  1124          getAllocationLocationTracker().freeAlloc(cell);
  1125        }
  1126      });
  1127
  1128      // Do *not* clear the mark bits. This is important to have a cheaper
  1129      // solution to a race condition in weakRefReadBarrier. If it gets
  1130      // interrupted between reading the concurrentPhase_ and checking the mark
  1131      // bits, the GC might finish. In that case, the mark bits will then be
  1132      // read to determine if the weak ref is live.
  1133      // Mark bits are reset before any new collection occurs, so there's no
  1134      // need to worry about their information being misused.
  1135    }
  1136    // TODO: Should probably check for cancellation, either via a
  1137    // promise/future pair or a condition variable.
  1138    concurrentPhase_.store(Phase::None, std::memory_order_release);
  1139  }
