  1662  void HadesGC::completeWeakMapMarking(MarkAcceptor &acceptor) {
  1663    gcheapsize_t weakMapAllocBytes = GCBase::completeWeakMapMarking(
  1664        this,
  1665        acceptor,
  1666        acceptor.reachableWeakMaps(),
  1667        /*objIsMarked*/
  1668        HeapSegment::getCellMarkBit,
  1669        /*markFromVal*/
  1670        [&acceptor](GCCell *valCell, HermesValue &valRef) {
  1671          if (HeapSegment::getCellMarkBit(valCell)) {
  1672            return false;
  1673          }
  1674          acceptor.accept(valRef);
  1675          // The weak ref lock is held throughout this entire section, so no need
  1676          // to re-lock it.
  1677          acceptor.drainMarkWorklist</*shouldLock*/ false>();
  1678          return true;
  1679        },
  1680        /*drainMarkStack*/
  1681        [](MarkAcceptor &acceptor) {
  1682          // The weak ref lock is held throughout this entire section, so no need
  1683          // to re-lock it.
  1684          acceptor.drainMarkWorklist</*shouldLock*/ false>();
  1685        },
  1686        /*checkMarkStackOverflow (HadesGC does not have mark stack overflow)*/
  1687        []() { return false; });
  1688
  1689    acceptor.reachableWeakMaps().clear();
  1690    (void)weakMapAllocBytes;
